    let x = n as i32;

    // Extract the four digits
    let d1 = x / 1000;         // thousands
    let d2 = (x / 100) % 10;   // hundreds
    let d3 = (x / 10) % 10;    // tens
    let d4 = x % 10;           // ones

    // Check if the first three are equal OR the last three are equal
